(function() {
    'use strict';

    class HorizonAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'HorizonMap';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleKey: 'round_1_title',
                    descKey: 'round_1_desc',
                    budgetMultiplier: 1.0,
                    h1Modifier: 0,
                    h2Modifier: 0,
                    h3Modifier: 0,
                    stakeholderModifier: 0
                },
                {
                    titleKey: 'round_2_title',
                    descKey: 'round_2_desc',
                    budgetMultiplier: 1.0,
                    h1Modifier: -0.01,
                    h2Modifier: 0,
                    h3Modifier: 0,
                    stakeholderModifier: -5
                },
                {
                    titleKey: 'round_3_title',
                    descKey: 'round_3_desc',
                    budgetMultiplier: 1.0,
                    h1Modifier: 0,
                    h2Modifier: -0.06,
                    h3Modifier: 0,
                    stakeholderModifier: -3
                },
                {
                    titleKey: 'round_4_title',
                    descKey: 'round_4_desc',
                    budgetMultiplier: 1.0,
                    h1Modifier: 0.02,
                    h2Modifier: 0,
                    h3Modifier: 0,
                    stakeholderModifier: -10
                },
                {
                    titleKey: 'round_5_title',
                    descKey: 'round_5_desc',
                    budgetMultiplier: 1.0,
                    h1Modifier: 0,
                    h2Modifier: 0,
                    h3Modifier: 0.15,
                    stakeholderModifier: 5
                },
                {
                    titleKey: 'round_6_title',
                    descKey: 'round_6_desc',
                    budgetMultiplier: 0.80,
                    h1Modifier: 0.02,
                    h2Modifier: -0.05,
                    h3Modifier: 0,
                    stakeholderModifier: -8
                },
                {
                    titleKey: 'round_7_title',
                    descKey: 'round_7_desc',
                    budgetMultiplier: 1.0,
                    h1Modifier: 0.01,
                    h2Modifier: 0.10,
                    h3Modifier: 0,
                    stakeholderModifier: 0
                },
                {
                    titleKey: 'round_8_title',
                    descKey: 'round_8_desc',
                    budgetMultiplier: 1.0,
                    h1Modifier: 0.01,
                    h2Modifier: 0,
                    h3Modifier: 0.05,
                    stakeholderModifier: 0
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    h1Revenue: 800,
                    h2Revenue: 120,
                    h3Revenue: 15,
                    cash: 500,
                    totalProfit: 0,
                    valuation: 3120,
                    prevValuation: 3120,
                    stakeholderScore: 65,
                    h3ConsecutiveRounds: 0,
                    h3BreakthroughAchieved: false,
                    h1RevenueHistory: [],
                    h2RevenueHistory: [],
                    h3RevenueHistory: [],
                    valuationHistory: [],
                    profitHistory: [],
                    stakeholderHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    h1Alloc: 50,
                    h2Alloc: 30,
                    h3Alloc: 20,
                    h2Strategy: 'maintain',
                    h3Strategy: 'maintain'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var h1Input = document.getElementById('h1AllocInput');
            var h2Input = document.getElementById('h2AllocInput');
            var h2Strat = document.getElementById('h2StrategySelect');
            var h3Strat = document.getElementById('h3StrategySelect');

            if (h1Input) decisions.h1Alloc = parseInt(h1Input.value) || 0;
            if (h2Input) decisions.h2Alloc = parseInt(h2Input.value) || 0;
            if (h2Strat) decisions.h2Strategy = h2Strat.value;
            if (h3Strat) decisions.h3Strategy = h3Strat.value;

            decisions.h3Alloc = 100 - decisions.h1Alloc - decisions.h2Alloc;

            if (decisions.h1Alloc < 0 || decisions.h2Alloc < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('alloc_negative_warning'), 'warning'
                );
                return false;
            }
            if (decisions.h3Alloc < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('alloc_over_warning'), 'warning'
                );
                return false;
            }
            if (decisions.h1Alloc + decisions.h2Alloc > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('alloc_over_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var roundIdx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var baseBudget = 200;
            var budgetMult = round.budgetMultiplier || 1.0;
            var totalBudget = Math.round(baseBudget * budgetMult);

            // --- H1 CORE BUSINESS ---
            var h1DeclineBase = 0.03;
            var h1AllocEffect = (d.h1Alloc - 35) * 0.001;
            var h1EventMod = round.h1Modifier || 0;
            var h1Decline = h1DeclineBase - h1AllocEffect + h1EventMod;
            h1Decline = Math.max(-0.02, Math.min(0.12, h1Decline));
            ds.h1Revenue = Math.round(ds.h1Revenue * (1 - h1Decline));
            var h1Profit = Math.round(ds.h1Revenue * 0.22);

            // --- H2 EMERGING BUSINESS ---
            var h2GrowthBase = 0.18;
            var h2AllocEffect = (d.h2Alloc - 25) * 0.004;
            var h2StratMod = 0;
            if (d.h2Strategy === 'accelerate') h2StratMod = 0.08;
            if (d.h2Strategy === 'reduce') h2StratMod = -0.10;
            var h2Variance = (Math.random() * 0.06) - 0.03;
            var h2EventMod = round.h2Modifier || 0;
            var h2Growth = h2GrowthBase + h2AllocEffect + h2StratMod + h2Variance + h2EventMod;
            h2Growth = Math.max(-0.15, Math.min(0.45, h2Growth));
            ds.h2Revenue = Math.round(ds.h2Revenue * (1 + h2Growth));
            var h2MarginBase = -0.05 + (ds.h2Revenue / 3000) * 0.20;
            h2MarginBase = Math.min(0.15, h2MarginBase);
            var h2Profit = Math.round(ds.h2Revenue * h2MarginBase);

            // --- H3 VENTURES ---
            if (d.h3Alloc >= 15) {
                ds.h3ConsecutiveRounds = (ds.h3ConsecutiveRounds || 0) + 1;
            } else {
                ds.h3ConsecutiveRounds = 0;
            }
            var h3StratMod = 1.0;
            if (d.h3Strategy === 'accelerate') h3StratMod = 1.5;
            if (d.h3Strategy === 'reduce') h3StratMod = 0.3;
            var h3BreakthroughProb = Math.min(0.6, d.h3Alloc * 0.005 * Math.max(ds.h3ConsecutiveRounds, 1) * h3StratMod);
            var h3EventMod = round.h3Modifier || 0;
            h3BreakthroughProb += h3EventMod;
            h3BreakthroughProb = Math.max(0, Math.min(0.7, h3BreakthroughProb));
            var h3Breakthrough = Math.random() < h3BreakthroughProb;

            if (h3Breakthrough && !ds.h3BreakthroughAchieved) {
                ds.h3Revenue = Math.round(ds.h3Revenue * (2.0 + Math.random() * 1.5));
                ds.h3BreakthroughAchieved = true;
            } else if (h3Breakthrough && ds.h3BreakthroughAchieved) {
                ds.h3Revenue = Math.round(ds.h3Revenue * (1.2 + Math.random() * 0.3));
            } else {
                var h3BaseGrowth = 0.05 + (d.h3Alloc * 0.002);
                var h3Var = (Math.random() * 0.10) - 0.05;
                ds.h3Revenue = Math.round(ds.h3Revenue * (1 + h3BaseGrowth + h3Var));
            }
            var h3Margin = ds.h3BreakthroughAchieved ? -0.02 : -0.15;
            var h3Profit = Math.round(ds.h3Revenue * h3Margin);

            // --- TOTALS ---
            var totalRevenue = ds.h1Revenue + ds.h2Revenue + ds.h3Revenue;
            var totalProfit = h1Profit + h2Profit + h3Profit - totalBudget;
            ds.totalProfit += totalProfit;
            ds.cash += totalProfit;

            // --- VALUATION ---
            var h1Multiple = 3.0;
            var h2Multiple = ds.h2Revenue > 200 ? 7.0 : 5.0;
            var h3Multiple = ds.h3BreakthroughAchieved ? 12.0 : 8.0;
            ds.valuation = Math.round(ds.h1Revenue * h1Multiple + ds.h2Revenue * h2Multiple + ds.h3Revenue * h3Multiple);

            // --- STAKEHOLDER SCORE ---
            var boardScore = 50;
            if (ds.valuation > ds.prevValuation) boardScore += 20;
            if (d.h1Alloc > 15 && d.h1Alloc < 60 && d.h2Alloc > 15 && d.h3Alloc > 10) boardScore += 20;
            if (totalProfit > 0) boardScore += 10;

            var investorScore = 50;
            if (h1Profit > 150) investorScore += 15;
            if (totalProfit > 0) investorScore += 20;
            if (d.h1Alloc > 40) investorScore += 10;
            if (h3Breakthrough) investorScore += 15;

            var employeeScore = 50;
            if (d.h2Alloc + d.h3Alloc > 40) employeeScore += 20;
            if (d.h3Alloc > 20) employeeScore += 10;
            if (d.h2Strategy === 'accelerate' || d.h3Strategy === 'accelerate') employeeScore += 10;

            var stakeEventMod = round.stakeholderModifier || 0;
            var stakeScore = Math.round((boardScore + investorScore + employeeScore) / 3) + stakeEventMod;
            stakeScore = Math.max(0, Math.min(100, stakeScore));
            ds.stakeholderScore = stakeScore;
            ds.prevValuation = ds.valuation;

            // Push to history arrays
            ds.h1RevenueHistory.push(ds.h1Revenue);
            ds.h2RevenueHistory.push(ds.h2Revenue);
            ds.h3RevenueHistory.push(ds.h3Revenue);
            ds.valuationHistory.push(ds.valuation);
            ds.profitHistory.push(totalProfit);
            ds.stakeholderHistory.push(stakeScore);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: period,
                h1Revenue: ds.h1Revenue,
                h2Revenue: ds.h2Revenue,
                h3Revenue: ds.h3Revenue,
                h1Profit: h1Profit,
                h2Profit: h2Profit,
                h3Profit: h3Profit,
                totalRevenue: totalRevenue,
                totalProfit: totalProfit,
                valuation: ds.valuation,
                stakeholderScore: stakeScore,
                h3Breakthrough: h3Breakthrough,
                budget: totalBudget
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('h1RevenueDisplay', 'domainState.h1Revenue',
                (v) => '$' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('h2RevenueDisplay', 'domainState.h2Revenue',
                (v) => '$' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('h3RevenueDisplay', 'domainState.h3Revenue',
                (v) => '$' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('valuationDisplay', 'domainState.valuation',
                (v) => '$' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('totalProfitDisplay', 'domainState.totalProfit',
                (v) => '$' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('stakeholderDisplay', 'domainState.stakeholderScore',
                (v) => Math.round(v) + '/100');

            var h1Input = document.getElementById('h1AllocInput');
            var h2Input = document.getElementById('h2AllocInput');
            var h3Display = document.getElementById('h3AllocDisplay');

            function updateH3() {
                var h1 = parseInt(h1Input.value) || 0;
                var h2 = parseInt(h2Input.value) || 0;
                var h3 = Math.max(0, 100 - h1 - h2);
                if (h3Display) h3Display.textContent = h3 + '%';
                if (h1 + h2 > 100 && h3Display) {
                    h3Display.style.color = '#c62828';
                } else if (h3Display) {
                    h3Display.style.color = '#e65100';
                }
            }
            if (h1Input) h1Input.addEventListener('input', updateH3);
            if (h2Input) h2Input.addEventListener('input', updateH3);
            updateH3();
        }

        getChartConfig() {
            return {
                revenueChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._t('chart_h1'),
                                data: [],
                                backgroundColor: 'rgba(21,101,192,0.75)',
                                borderColor: '#1565c0',
                                borderWidth: 1
                            },
                            {
                                label: this._t('chart_h2'),
                                data: [],
                                backgroundColor: 'rgba(46,125,50,0.75)',
                                borderColor: '#2e7d32',
                                borderWidth: 1
                            },
                            {
                                label: this._t('chart_h3'),
                                data: [],
                                backgroundColor: 'rgba(230,81,0,0.75)',
                                borderColor: '#e65100',
                                borderWidth: 1
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_revenue_title') }
                        },
                        scales: {
                            x: { stacked: true },
                            y: { stacked: true, beginAtZero: true }
                        }
                    }
                },
                valuationChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._t('chart_valuation_label'),
                            data: [],
                            borderColor: '#6a1b9a',
                            backgroundColor: 'rgba(106,27,154,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_valuation_title') }
                        },
                        scales: {
                            y: { beginAtZero: false }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = state.domainState;
            var labels = ds.h1RevenueHistory.map(function(_, i) { return 'Y' + (i + 1); });
            return {
                revenueChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.h1RevenueHistory },
                        { data: ds.h2RevenueHistory },
                        { data: ds.h3RevenueHistory }
                    ]
                },
                valuationChart: {
                    labels: labels,
                    datasets: [{ data: ds.valuationHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var profits = history.map(function(r) { return r.results ? r.results.totalProfit || 0 : 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var avgProfit = Math.round(totalProfit / profits.length);

            var lastRecord = history[history.length - 1];
            var finalValuation = lastRecord && lastRecord.results ? lastRecord.results.valuation || 0 : 0;

            var stakeScores = history.map(function(r) { return r.results ? r.results.stakeholderScore || 0 : 0; });
            var avgStakeholder = Math.round(stakeScores.reduce(function(s, v) { return s + v; }, 0) / stakeScores.length);

            var performance = this._t('perf_needs');
            if (finalValuation > 4000 && avgStakeholder > 55) performance = this._t('perf_good');
            if (finalValuation > 5500 && avgStakeholder > 65) performance = this._t('perf_excellent');
            if (finalValuation > 7000 && avgStakeholder > 75) performance = this._t('perf_outstanding');

            var insights = [];
            var lastH1 = lastRecord && lastRecord.results ? lastRecord.results.h1Revenue || 0 : 0;
            var lastH2 = lastRecord && lastRecord.results ? lastRecord.results.h2Revenue || 0 : 0;
            var lastH3 = lastRecord && lastRecord.results ? lastRecord.results.h3Revenue || 0 : 0;

            if (lastH2 > lastH1 * 0.5) {
                insights.push(this._t('insight_h2_strong'));
            } else {
                insights.push(this._t('insight_h2_weak'));
            }
            if (lastH3 > 50) {
                insights.push(this._t('insight_h3_strong'));
            } else {
                insights.push(this._t('insight_h3_weak'));
            }
            if (avgStakeholder >= 65) {
                insights.push(this._t('insight_stake_good'));
